import { createCombobox } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createEffect, createMemo, createSignal, For, merge, Show } from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

/** An option: a string that is both its label and its value, or an object with a value and a label. */
export type ComboboxItem = string | { readonly value: string; readonly label: string };

export interface ComboboxProps {
  /** The options, declared once: the primitive filters their labels as the reader types. */
  readonly items: ReadonlyArray<ComboboxItem>;
  /** Controlled: the chosen value. Leave it out and the combobox owns it. */
  readonly value?: string | null;
  /** Uncontrolled starting value. */
  readonly defaultValue?: string | null;
  /** A request to choose a value; the primitive only commits an option. */
  readonly onValueChange?: (value: string | null) => void;
  /** A request to open or close the popup. */
  readonly onOpenChange?: (open: boolean) => void;
  /** Shown in the field while it holds no text. */
  readonly placeholder?: string;
  /** The accessible name: it names the field and the listbox. */
  readonly label?: string;
  /** Shown inside the list while nothing matches the typed text. @default "No matches" */
  readonly emptyMessage?: string;
  /** A disabled combobox keeps its tab stop, never opens and changes nothing (the primitive's `aria-disabled`). */
  readonly disabled?: boolean;
  readonly id?: string;
  readonly class?: string;
}

const DEFAULT_EMPTY = "No matches";

// The field and the list share one anchor, as the menu and the tooltip do: `position: relative` here and the list is
// absolute in it, so no rect is measured and nothing listens to scroll or resize.
const anchorClass = css.cn(css.position("relative"), css.display("grid"), css.minWidth("16rem"));

// The field is the kit's `Input` with the list's own surface under it: one border, one radius and the ring a control wears.
// `placeholder-shown` keeps the hint in the placeholder tone without a `::placeholder` rule of its own.
const fieldClass = css.cn(
  css.boxSizing("border-box"),
  css.display("block"),
  css.width("100%"),
  css.padding(t.space._2, t.space._3),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.md),
  css.bg(t.color.surface),
  css.color(t.color.fieldText),
  css.fontSize(t.font.size),
  css.placeholderShown(css.color(t.color.placeholder)),
  css.hover(css.border("1px solid", t.color.borderHover)),
  css.focusVisible(
    css.outline("2px solid", t.color.focusRing),
    css.outlineOffset("2px"),
    css.border("1px solid", t.color.focusRing),
  ),
  css.attr("aria-disabled", "true")(
    css.bg(t.color.page),
    css.color(t.color.textDisabled),
    css.border("1px solid", t.color.borderDisabled),
    css.cursor("not-allowed"),
  ),
);

// The popup is the select's list: the overlay surface, the popover shadow and the same radius, so the two read as siblings.
// `max-height` bounds the rows and this is what lets the list scroll under them. No `display`: the primitive's `hidden`
// attribute is what hides it, and a display here would override the UA's rule.
const listClass = css.cn(
  css.position("absolute"),
  css.insetBlockStart("100%"),
  css.insetInlineStart("0"),
  css.marginBlockStart(t.space._1),
  // as in Menu and Dialog: the custom property is the token, because `z-index` takes an `<integer>`
  css.zIndex("var(--z-popover)"),
  css.width("max-content"),
  css.minWidth("100%"),
  css.maxHeight("15rem"),
  css.overflowY("auto"),
  css.padding(t.space._1),
  css.bg(t.color.overlayBackground),
  css.color(t.color.text),
  css.border("1px solid", t.color.overlayBorder),
  css.borderRadius(t.radius.lg),
  css.boxShadow(t.shadow.popover),
);

// The active option is the primitive's announcement: focus stays in the field and `aria-selected` marks the row that Enter
// would commit, so the paint follows that attribute and the skin keeps no copy of the active index.
const optionClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.padding(t.space._1, t.space._2),
  css.borderRadius(t.radius.sm),
  css.fontSize(t.font.size),
  css.color(t.color.text),
  css.cursor("pointer"),
  css.attr("aria-selected", "true")(css.bg(t.color.buttonBackground)),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.transition("background-color 120ms ease-out"),
  ),
);

const emptyClass = css.cn(
  css.padding(t.space._3, t.space._2),
  css.fontSize(t.font.size),
  css.color(t.color.muted),
  css.textAlign("center"),
);

/**
 * APG combobox (autocomplete variant), styled: a text field with a listbox popup. `createCombobox` owns the open state, the
 * selection, the prefix filter, the active option, `aria-expanded` / `aria-controls` / `aria-activedescendant`, the arrows,
 * Enter, Space, Escape, Tab and the blur that commits, and the option ids; DOM focus never leaves the field. The skin owns
 * the anchor, the field and the list surfaces, the highlight painted from `aria-selected`, the empty state, the label and
 * the field's own display of the chosen label after the primitive clears its filter text.
 */
export const Combobox = (props: ComboboxProps): JSX.Element => {
  // read once: the primitive takes its corpus up front (`options` is not an accessor), and the field needs the labels too
  const labels = new Map(
    props.items.map((item) =>
      typeof item === "string" ? [item, item] : [item.value, item.label],
    ),
  );
  const combobox = createCombobox({
    options: props.items,
    get value() {
      return props.value;
    },
    defaultValue: props.defaultValue ?? null,
    filter: true,
    autoComplete: "list",
    id: props.id,
    get disabled() {
      return props.disabled;
    },
    get onValueChange() {
      return props.onValueChange;
    },
    get onOpenChange() {
      return props.onOpenChange;
    },
    // Tab: the primitive has committed and closed, and says the DOM host may let go of native focus
    onFocusRelease: () => {
      if (document.activeElement instanceof HTMLElement) {
        document.activeElement.blur();
      }
    },
  });
  const input = combobox.comboboxProps;

  // The primitive's field text is the filter query, which it clears on commit; the display goes back to the chosen label
  // whenever the popup is closed, so the field shows the selection again after Enter, Escape or a blur.
  const [editing, setEditing] = createSignal(false);
  createEffect(
    () => combobox.open(),
    (open) => {
      if (!open) {
        setEditing(false);
      }
    },
  );

  const display = (): string => {
    // a key that starts the filter has changed `query` before any input event arrives, so the query is the field's text
    if (editing() || combobox.query() !== "") {
      return combobox.query();
    }
    const value = combobox.value();
    return value === null ? "" : (labels.get(value) ?? value);
  };

  // One row per match, with the primitive's announcement read in the memo: the list rebuilds when the filter, the active
  // option or the selection changes, and the JSX itself holds no copy of the active index.
  const rows = createMemo(() =>
    combobox.options().map((option) => ({
      id: option.props.id,
      role: option.props.role,
      label: option.label,
      selected: option.props["aria-selected"],
      onClick: option.props.onClick,
      onMouseDown: option.props.onMouseDown,
    })),
  );

  const merged = merge(input, () => ({
    type: "text",
    autocomplete: "off",
    spellcheck: false,
    "data-part": "combobox-input",
    get value() {
      return display();
    },
    get placeholder() {
      return props.placeholder;
    },
    get "aria-label"() {
      return props.label;
    },
    get class() {
      return fieldClass;
    },
    onInput: (event: InputEvent & { readonly currentTarget: HTMLInputElement }) => {
      if (props.disabled === true) {
        // the primitive drops the input; the skin puts the field back where the model is
        event.currentTarget.value = display();
        return;
      }
      input.onInput(event);
      setEditing(true);
    },
    onFocus: (event: FocusEvent & { readonly currentTarget: HTMLInputElement }) => {
      input.onFocus();
      // the chosen label is in the field: selecting it lets the first typed character replace it
      event.currentTarget.select();
    },
  }));

  return (
    <div data-part="combobox" class={css.cn(anchorClass, props.class)}>
      <input {...merged} />
      <div
        {...combobox.listboxProps}
        data-part="combobox-listbox"
        aria-label={props.label}
        class={listClass}
      >
        <For each={rows()}>
          {(row) => (
            <div
              id={row.id}
              role={row.role}
              aria-selected={row.selected}
              onClick={row.onClick}
              onMouseDown={row.onMouseDown}
              data-part="combobox-option"
              class={optionClass}
            >
              {row.label}
            </div>
          )}
        </For>
        <Show when={combobox.open() && combobox.options().length === 0}>
          <div data-part="combobox-empty" class={emptyClass}>
            {props.emptyMessage ?? DEFAULT_EMPTY}
          </div>
        </Show>
      </div>
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import { createSignal } from "solid-js";

import { Combobox, type ComboboxItem } from "./combobox.tsx";

/**
 * Twelve names from a component library, the corpus the demo filters. The value is the slug a page would save; the label
 * is what the field shows and what the reader types against.
 */
export const COMBOBOX_ITEMS: ReadonlyArray<ComboboxItem> = [
  { value: "accordion", label: "Accordion" },
  { value: "button", label: "Button" },
  { value: "checkbox", label: "Checkbox" },
  { value: "combobox", label: "Combobox" },
  { value: "dialog", label: "Dialog" },
  { value: "drawer", label: "Drawer" },
  { value: "field", label: "Field" },
  { value: "menu", label: "Menu" },
  { value: "radio", label: "Radio group" },
  { value: "select", label: "Select" },
  { value: "slider", label: "Slider" },
  { value: "switch", label: "Switch" },
];

/** The field's accessible name: what the searchable list is of. */
export const COMBOBOX_LABEL = "Component";

/** The one sentence the demo says about typing and the keys. */
export const COMBOBOX_HINT =
  "Type to filter the list, then press ↑ or ↓ to move the highlight, Enter or Space to choose, and Escape to close it.";

export interface ComboboxExampleProps {
  readonly class?: string | undefined;
  readonly disabled?: boolean | undefined;
  /** What a page would save: the chosen slug, or `null` while nothing is chosen. */
  readonly onValueChange?: ((value: string | null) => void) | undefined;
}

/**
 * The starter in ordinary use: a searchable picker of component names, the chosen one shown in the field, and a sentence
 * about typing and the keys. A page copies this and swaps `COMBOBOX_ITEMS` for its own list and `onValueChange` for its
 * own save.
 */
export const ComboboxExample = (props: ComboboxExampleProps): JSX.Element => {
  const [value, setValue] = createSignal<string | null>(null);
  return (
    <div class={props.class === undefined ? "demo-column" : `demo-column ${props.class}`}>
      <Combobox
        items={COMBOBOX_ITEMS}
        label={COMBOBOX_LABEL}
        placeholder="Search components"
        value={value()}
        disabled={props.disabled}
        onValueChange={(next) => {
          setValue(next);
          props.onValueChange?.(next);
        }}
      />
      <p class="demo-text">{COMBOBOX_HINT}</p>
    </div>
  );
};

/** What a mounted demo hands the test: where it lives, the values the host heard, and a teardown. */
export interface MountedCombobox {
  readonly root: HTMLElement;
  /** Every `onValueChange` the host received, oldest first. */
  readonly changes: () => ReadonlyArray<string | null>;
  readonly dispose: () => void;
}

/** Mounts the styled picker at the demo's width. The primitive owns the filter, the highlight and the keys. */
export const mountCombobox = (config: { readonly disabled?: boolean } = {}): MountedCombobox => {
  const root = document.createElement("div");
  root.style.width = "24rem";
  document.body.append(root);
  const changes: Array<string | null> = [];
  const dispose = render(
    () => (
      <ComboboxExample
        disabled={config.disabled}
        onValueChange={(value) => {
          changes.push(value);
        }}
      />
    ),
    root,
  );
  return {
    root,
    changes: () => changes,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { flush } from "solid-js";
import { afterEach, describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import { COMBOBOX_LABEL, type MountedCombobox, mountCombobox } from "./combobox.fixture";

// @cssints/headless walks `createCombobox` against the APG combobox specs in test/combobox.browser.test.tsx, so that file
// is the primitive's oracle. This file is the skin's: it mounts the starter in a real Chromium, reads the field and the
// listbox the primitive built, and types, keys and picks the way a reader does. The filter, the active option and every
// `aria-*` are the primitive's; the field's display of the chosen label after a commit is the skin's.

/** Solid 2 applies setters and the primitive's effects on later turns. */
const settle = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 20));

/** A frame for the computed styles, after a transition has been given time to start. */
const frame = (): Promise<void> =>
  new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));

const waitFor = async (done: () => boolean, limit = 2000): Promise<void> => {
  const start = performance.now();
  while (!done()) {
    if (performance.now() - start > limit) {
      throw new Error("waitFor timed out");
    }
    await frame();
  }
};

const live: MountedCombobox[] = [];

const mounted = (config?: Parameters<typeof mountCombobox>[0]): MountedCombobox => {
  const instance = mountCombobox(config);
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const required = <T extends Element>(parent: ParentNode, selector: string): T => {
  const element = parent.querySelector<T>(selector);
  if (element === null) {
    throw new Error(`combobox: no ${selector}`);
  }
  return element;
};

const field = (root: ParentNode): HTMLInputElement =>
  required<HTMLInputElement>(root, '[data-part="combobox-input"]');

const list = (root: ParentNode): HTMLElement => required(root, '[data-part="combobox-listbox"]');

const rows = (root: ParentNode): ReadonlyArray<HTMLElement> => [
  ...root.querySelectorAll<HTMLElement>('[data-part="combobox-option"]'),
];

const labels = (root: ParentNode): ReadonlyArray<string> =>
  rows(root).map((row) => row.textContent ?? "");

const activeId = (root: ParentNode): string | null =>
  field(root).getAttribute("aria-activedescendant");

const style = (element: Element): CSSStyleDeclaration => getComputedStyle(element);

/** Real typing in the field, replacing what is there, as a reader's first character does. */
const type = async (root: ParentNode, text: string): Promise<void> => {
  const input = field(root);
  input.focus();
  input.select();
  await userEvent.keyboard(text);
  flush();
  await settle();
};

/** A key on the focused field, as a reader's would arrive. */
const press = async (root: ParentNode, key: string): Promise<void> => {
  field(root).dispatchEvent(
    new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true }),
  );
  flush();
  await settle();
};

describe("Combobox", () => {
  it("is a named combobox field whose popup is a listbox of options", async () => {
    const { root } = mounted();
    await settle();

    const input = field(root);
    expect(input.getAttribute("role")).toBe("combobox");
    expect(input.getAttribute("aria-label")).toBe(COMBOBOX_LABEL);
    expect(input.getAttribute("aria-haspopup")).toBe("listbox");
    expect(input.getAttribute("aria-expanded")).toBe("false");
    // closed: no popup is named and no option is active
    expect(input.getAttribute("aria-controls")).toBeNull();
    expect(input.getAttribute("aria-activedescendant")).toBeNull();
    expect(input.value).toBe("");

    const box = list(root);
    expect(box.getAttribute("role")).toBe("listbox");
    expect(box.getAttribute("aria-label")).toBe(COMBOBOX_LABEL);
    expect(box.hidden).toBe(true);

    const all = rows(root);
    expect(all).toHaveLength(12);
    expect(all.every((row) => row.getAttribute("role") === "option")).toBe(true);
    // every row has the primitive's own id, and none of them is announced while the popup is closed
    expect(new Set(all.map((row) => row.id)).size).toBe(12);
    expect(all.every((row) => row.getAttribute("aria-selected") === "false")).toBe(true);
  });

  it("filters as the reader types, and the listbox holds the matches with the first one active", async () => {
    const { root } = mounted();
    await settle();

    await type(root, "s");

    const input = field(root);
    expect(input.value).toBe("s");
    expect(input.getAttribute("aria-expanded")).toBe("true");
    expect(input.getAttribute("aria-controls")).toBe(list(root).id);
    expect(list(root).hidden).toBe(false);
    expect(labels(root)).toEqual(["Select", "Slider", "Switch"]);

    const all = rows(root);
    expect(input.getAttribute("aria-activedescendant")).toBe(all[0]?.id);
    expect(all.map((row) => row.getAttribute("aria-selected"))).toEqual([
      "true",
      "false",
      "false",
    ]);
    // the active row is painted from the announcement, not from a copy of the active index
    await waitFor(
      () => style(all[0]!).backgroundColor !== style(all[1]!).backgroundColor,
    );
  });

  it("moves the active option with the arrows, and aria-activedescendant follows it", async () => {
    const { root } = mounted();
    await settle();

    await type(root, "s");
    const input = field(root);
    expect(activeId(root)).toBe(rows(root)[0]?.id);

    await press(root, "ArrowDown");
    expect(activeId(root)).toBe(rows(root)[1]?.id);
    expect(rows(root)[1]?.getAttribute("aria-selected")).toBe("true");
    expect(rows(root)[0]?.getAttribute("aria-selected")).toBe("false");

    await press(root, "ArrowDown");
    expect(activeId(root)).toBe(rows(root)[2]?.id);

    // the end holds: one more down stays on the last match
    await press(root, "ArrowDown");
    expect(activeId(root)).toBe(rows(root)[2]?.id);

    await press(root, "ArrowUp");
    expect(activeId(root)).toBe(rows(root)[1]?.id);
    await press(root, "ArrowUp");
    expect(activeId(root)).toBe(rows(root)[0]?.id);
    // and the start holds
    await press(root, "ArrowUp");
    expect(activeId(root)).toBe(rows(root)[0]?.id);
  });

  it("picks the active option with Enter or Space, and the field shows the chosen label", async () => {
    const { root, changes } = mounted();
    await settle();

    await type(root, "d");
    expect(labels(root)).toEqual(["Dialog", "Drawer"]);
    await press(root, "ArrowDown");
    await press(root, "Enter");

    const input = field(root);
    expect(list(root).hidden).toBe(true);
    expect(input.getAttribute("aria-expanded")).toBe("false");
    expect(input.getAttribute("aria-activedescendant")).toBeNull();
    expect(input.value).toBe("Drawer");
    expect(document.activeElement).toBe(input);
    expect(changes()).toEqual(["drawer"]);

    // Space commits the active row too, and the field replaces its display with the next choice
    await type(root, "sw");
    expect(labels(root)).toEqual(["Switch"]);
    await press(root, " ");
    expect(field(root).value).toBe("Switch");
    expect(list(root).hidden).toBe(true);
    expect(changes()).toEqual(["drawer", "switch"]);
  });

  it("closes on Escape, keeps the focus in the field, and shows the chosen label again", async () => {
    const { root } = mounted();
    await settle();

    await type(root, "di");
    await press(root, "Enter");
    expect(field(root).value).toBe("Dialog");

    await type(root, "s");
    expect(list(root).hidden).toBe(false);

    await press(root, "Escape");
    const input = field(root);
    expect(list(root).hidden).toBe(true);
    expect(input.getAttribute("aria-expanded")).toBe("false");
    expect(input.getAttribute("aria-activedescendant")).toBeNull();
    expect(document.activeElement).toBe(input);
    // the filter text is gone and the field reads the selection again
    expect(input.value).toBe("Dialog");
  });

  it("says so when nothing matches", async () => {
    const { root } = mounted();
    await settle();

    await type(root, "zzz");
    expect(rows(root)).toHaveLength(0);
    expect(field(root).getAttribute("aria-expanded")).toBe("true");
    expect(field(root).getAttribute("aria-activedescendant")).toBeNull();

    const empty = required(root, '[data-part="combobox-empty"]');
    expect(empty.textContent).toBe("No matches");
  });

  it("never opens while disabled, and the field keeps the model's text", async () => {
    const { root, changes } = mounted({ disabled: true });
    await settle();

    const input = field(root);
    expect(input.getAttribute("aria-disabled")).toBe("true");
    // the pattern keeps the tab stop and announces the state; it is not a native disabled input
    expect(input.hasAttribute("disabled")).toBe(false);

    // a click and a key are dropped before they become a request, and focus does not change the picture
    input.focus();
    input.click();
    flush();
    await settle();
    await press(root, "ArrowDown");
    expect(input.getAttribute("aria-expanded")).toBe("false");
    expect(list(root).hidden).toBe(true);
    expect(input.getAttribute("aria-activedescendant")).toBeNull();

    // the input event is dropped too: the DOM text goes back to what the model holds
    input.value = "s";
    input.dispatchEvent(new InputEvent("input", { bubbles: true }));
    flush();
    await settle();
    expect(input.getAttribute("aria-expanded")).toBe("false");
    expect(input.value).toBe("");
    expect(changes()).toEqual([]);
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

